roots=[]
for i,d in items.items():
    p=(d.get('metadata') or {}).get('parent')
    if p: kids[p].append(i)
    else: roots.append(i)
def pr(i,depth):
    d=items[i]
    md=d.get('metadata') or {}
    print('  '*depth+f"{i}  [{d.get('status')}] owner={md.get('owner')} ms={md.get('milestone')} pin={md.get('pin_commit') or md.get('pinned_commit')}")
    for k in sorted(kids[i]): pr(k,depth+1)
for r in sorted(roots): pr(r,0)
print('TOTAL',len(items))
print('STATUS COUNTS',collections.Counter(d.get('status') for d in items.values()))
